import java.util.*;

// ID から名前を探す(見つからなければ空の Optional)
Optional<String> findName(int id) {
    if (id == 1) return Optional.of("佐藤");
    if (id == 2) return Optional.of("鈴木");
    return Optional.empty();
}

// ここを変えてみよう:id を 1 や 2 にする
int id = 3;

// ① 既定値で取り出す
String name = findName(id).orElse("ゲスト");
System.out.println("① orElse          : " + name);

// ② あるときだけ処理/ないときは別の処理
findName(id).ifPresentOrElse(
    n -> System.out.println("② こんにちは " + n + " さん"),
    () -> System.out.println("② ID " + id + " は未登録"));

// ③ なければ例外にする
try {
    String must = findName(id).orElseThrow(
        () -> new IllegalArgumentException("ID不明: " + id));
    System.out.println("③ orElseThrow     : " + must);
} catch (IllegalArgumentException e) {
    System.out.println("③ 例外 → " + e.getMessage());
}

// ④ get() は空だと NoSuchElementException(アンチパターン)
try {
    String g = findName(id).get();
    System.out.println("④ get()           : " + g);
} catch (NoSuchElementException e) {
    System.out.println("④ get() で例外 → " + e.getMessage());
}

