import java.util.*;

class Dept {
    private final String name;
    Dept(String name) { this.name = name; }
    String getName() { return name; }
}

class Employee {
    private final String name;
    private final Dept dept;
    Employee(String name, Dept dept) {
        this.name = name;
        this.dept = dept;
    }
    String getName() { return name; }
    Dept getDept() { return dept; }
}

public class Main {
    static String deptNameOld(Employee emp) {
        String result = "未所属";
        if (emp != null) {
            Dept d = emp.getDept();
            if (d != null && d.getName() != null) {
                result = d.getName();
            }
        }
        return result;
    }

    static String deptName(Employee emp) {
        return Optional.ofNullable(emp)
            .map(Employee::getDept)
            .map(Dept::getName)
            .filter(s -> !s.isBlank()) // 空白だけもなし扱い
            .orElse("未所属");
    }

    public static void main(String[] args) {
        // ここを変えてみよう:部署名を "" や " " にしてみる
        List<Employee> list = new ArrayList<>();
        list.add(new Employee("佐藤", new Dept("開発")));
        list.add(new Employee("鈴木", null));
        list.add(new Employee("田中", new Dept(null)));
        list.add(null);

        for (Employee e : list) {
            String who =
                (e == null) ? "(null)" : e.getName();
            System.out.println(who + " → if版: "
                + deptNameOld(e) + " / Optional版: "
                + deptName(e));
        }
    }
}

import java.util.*;

public class Main {
    // ここを変えてみよう:timeout を "" や "  " にする / "app.timeout" のキー名を変える
    static Map<String, String> conf = Map.of(
        "app.name", "Java道場",
        "app.timeout", " 30 ",
        "app.port", "8080");

    static Optional<String> get(String key) {
        return Optional.ofNullable(conf.get(key))
            .map(String::strip)
            .filter(s -> !s.isEmpty());
    }

    public static void main(String[] args) {
        String name = get("app.name").orElse("名無し");
        int timeout = get("app.timeout")
            .map(Integer::parseInt)
            .orElse(10);
        String mode = get("app.mode").orElse("dev");
        System.out.println(name + " / timeout=" + timeout
            + " / mode=" + mode);

        // 「app.p」で始まるキーのうち、辞書順で最初のもの
        String firstKey = conf.keySet().stream()
            .sorted()
            .filter(k -> k.startsWith("app.p"))
            .findFirst()
            .orElse("なし");
        System.out.println("app.p で始まる最初のキー: " + firstKey);
    }
}

